<?php
$taskId = valid_id($_GET['id'] ?? null);
$task = get_task($pdo, $taskId);
$progress = task_progress($pdo, $taskId);
$itemsStmt = $pdo->prepare('SELECT * FROM task_items WHERE task_id = ? ORDER BY sort_order, id');
$itemsStmt->execute([$taskId]);
$items = $itemsStmt->fetchAll();
$notesStmt = $pdo->prepare('SELECT * FROM task_notes WHERE task_id = ? ORDER BY created_at DESC, id DESC');
$notesStmt->execute([$taskId]);
$notes = $notesStmt->fetchAll();
$activityStmt = $pdo->prepare('SELECT * FROM activity_logs WHERE task_id = ? ORDER BY created_at DESC, id DESC LIMIT 30');
$activityStmt->execute([$taskId]);
$activities = $activityStmt->fetchAll();
$assigneeStmt = $pdo->prepare('SELECT u.id, u.name, u.email FROM task_assignees ta INNER JOIN users u ON u.id = ta.user_id WHERE ta.task_id = ? ORDER BY u.name');
$assigneeStmt->execute([$taskId]);
$assignees = $assigneeStmt->fetchAll();
$commentStmt = $pdo->prepare('SELECT tc.*, u.name AS author_name FROM task_comments tc LEFT JOIN users u ON u.id = tc.user_id WHERE tc.task_id = ? ORDER BY tc.created_at ASC, tc.id ASC');
$commentStmt->execute([$taskId]);
$comments = $commentStmt->fetchAll();
$deadline = task_deadline($task);
?>
